import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u15")
C = "A2-B1"

L(1, "En, maar, of, want: ordem normal", "As conjunções coordenativas não mudam a ordem.",
  ["Ligar orações com en, maar, of, want sem alterar a ordem"],
  vocab=[V("v-of-ou","of (ou)","ou","conjunction"), V("v-maar-conj","maar (conj.)","mas","conjunction"),
         V("v-en-conj","en (conj.)","e","conjunction"), V("v-nevenschikkend","coördinerend voegwoord","conjunção coordenativa","expression")],
  ex=[("Ik ben moe, maar ik ga toch mee.","Estou cansado, mas vou na mesma."),("Wil je thee of drink je liever koffie?","Queres chá ou preferes café?"),("Ik werk en mijn man studeert.","Eu trabalho e o meu marido estuda."),("Ik blijf thuis, want ik ben ziek.","Fico em casa, porque estou doente.")],
  gram=[G("g-en-maar-of-want","Coordenativas: ordem normal","**en, maar, of, want** ligam duas orações principais. Depois delas, a ordem é a **normal**: sujeito + verbo: *…, maar **ik ga** toch mee.* Uma forma de memorizar: estas conjunções «não contam» como posição.",
    [("Het regent, maar het is niet koud.","Está a chover, mas não está frio.")],
    "É a ordem mais parecida com a do português.")],
  review=["v-en","v-maar","v-want","v-of"],
  cefr=C, exs=[
    MA([("en","e"),("maar","mas"),("of","ou"),("want","porque")], "Coordenativas.", ["v-en-conj","v-maar-conj","v-of-ou","v-want"]),
    WO("Estou cansado, mas vou na mesma.", ["Ik","ben","moe,","maar","ik","ga","toch","mee"], "maar + ordem normal.", ["v-maar-conj"]),
    WO("Queres chá ou preferes café?", ["Wil","je","thee","of","drink","je","liever","koffie?"], "of + pergunta.", ["v-of-ou"]),
    FE(["Ik","blijf","thuis,","want","ben","ik","ziek."], 4, "ik ben", "Depois de want, ordem normal: want ik ben ziek.", ["v-want"]),
    FE(["Het","regent,","maar","is","het","niet","koud."], 3, "het is", "Depois de maar, ordem normal: maar het is niet koud.", ["v-maar-conj"]),
    TR("pt-nl","Eu trabalho e o meu marido estuda.", ["Ik werk en mijn man studeert"], "en.", ["v-en-conj"]),
    TR("nl-pt","Ik blijf thuis, want ik ben ziek.", ["Fico em casa, porque estou doente","Fico em casa, pois estou doente"], "want.", ["v-want"]),
    MC("Depois de «want» a ordem é…", ["*normal (sujeito + verbo)","verbo no fim|Isso é omdat.","verbo + sujeito|Isso é inversão."], "want = coordenativa.", ["v-want"]),
    FB("Wil je fietsen ___ zullen we de bus nemen?", ["of"], "ou.", ["v-of-ou"], choices=["of","want","dus"], tr="Queres ir de bicicleta ou apanhamos o autocarro?"),
    LI("Ik wil graag mee, maar ik heb geen tijd.", ["Ik wil graag mee(,) maar ik heb geen tijd"], "Gostava de ir, mas não tenho tempo.", "maar.", ["v-maar-conj"]),
  ], diff=3, mins=6)

L(2, "Want ou omdat? Maar ou hoewel?", "Mesma ideia, ordem diferente.",
  ["Escolher entre conjunções coordenativas e subordinativas"],
  vocab=[V("v-voegwoord","voegwoord","conjunção","noun","het"), V("v-zin-deel","bijzin","oração subordinada","noun","de"),
         V("v-hoofdzin","hoofdzin","oração principal","noun","de"), V("v-woordvolgorde","woordvolgorde","ordem das palavras","noun","de")],
  ex=[("Ik ga niet, want ik heb geen zin.","Não vou, porque não me apetece."),("Ik ga niet, omdat ik geen zin heb.","Não vou porque não me apetece."),("Het is koud, maar ik ga zwemmen.","Está frio, mas vou nadar."),("Hoewel het koud is, ga ik zwemmen.","Embora esteja frio, vou nadar.")],
  gram=[G("g-hoofdzin-bijzin","Principal vs. subordinada","Coordenativas (**en, maar, of, want**) → **ordem normal**. Subordinativas (**dat, omdat, als, toen, hoewel, terwijl, zodat, of = se…**) → **verbo no fim**. Pares com sentido parecido: *want/omdat* (porque), *maar/hoewel* (mas/embora).",
    [("Ik kom later, want de trein heeft vertraging.","Chego mais tarde, porque o comboio está atrasado."),("Ik kom later omdat de trein vertraging heeft.","Chego mais tarde porque o comboio está atrasado.")])],
  review=["v-want","v-omdat","v-hoewel","v-maar-conj"],
  cefr=C, exs=[
    MA([("voegwoord","conjunção"),("bijzin","oração subordinada"),("hoofdzin","oração principal"),("woordvolgorde","ordem das palavras")], "Gramática.", ["v-voegwoord","v-zin-deel","v-hoofdzin","v-woordvolgorde"]),
    FB("Ik ga niet, ___ ik heb geen zin.", ["want"], "Ordem normal → want.", ["v-want"], choices=["want","omdat","hoewel"], tr="Não vou, porque não me apetece."),
    FB("Ik ga niet, ___ ik geen zin heb.", ["omdat"], "Verbo no fim → omdat.", ["v-omdat"], choices=["omdat","want","maar"], tr="Não vou porque não me apetece."),
    FB("___ het koud is, ga ik zwemmen.", ["Hoewel"], "Verbo no fim + vírgula + verbo.", ["v-hoewel"], choices=["Hoewel","Maar","Want"], tr="Embora esteja frio, vou nadar."),
    FB("Het is koud, ___ ik ga zwemmen.", ["maar"], "Ordem normal → maar.", ["v-maar-conj"], choices=["maar","hoewel","omdat"], tr="Está frio, mas vou nadar."),
    TR("pt-nl","Chego mais tarde porque o comboio está atrasado. (use omdat)", ["Ik kom later omdat de trein vertraging heeft","Ik ben later omdat de trein vertraging heeft"], "omdat + verbo no fim.", ["v-omdat"]),
    TR("pt-nl","Chego mais tarde, porque o comboio está atrasado. (use want)", ["Ik kom later(,) want de trein heeft vertraging","Ik ben later(,) want de trein heeft vertraging"], "want + ordem normal.", ["v-want"]),
    AR("voegwoord","a conjunção","het", "Het voegwoord.", ["v-voegwoord"]),
    MC("Qual destas é subordinativa (verbo no fim)?", ["*terwijl","en|Coordenativa.","maar|Coordenativa."], "terwijl.", ["v-zin-deel"]),
    MC("Qual está errada?", ["*Ik bel je, want ik je nummer heb.","Ik bel je, want ik heb je nummer.|Está certa.","Ik bel je omdat ik je nummer heb.|Está certa."], "want → ordem normal.", ["v-want"]),
  ], diff=4, mins=7)

L(3, "Dus, toch, daarom, daarna", "Advérbios de ligação com inversão.",
  ["Usar advérbios de ligação com inversão"],
  vocab=[V("v-dus-conj","dus","portanto|então","adverb",note="Het regent, dus ik neem de bus."), V("v-toch-conj","toch","mesmo assim|contudo","adverb"),
         V("v-bovendien","bovendien","além disso","adverb"), V("v-anders","anders","senão|caso contrário","adverb")],
  ex=[("Het regent, dus neem ik de bus.","Está a chover, portanto apanho o autocarro."),("Het was duur, toch heb ik het gekocht.","Era caro; mesmo assim comprei-o."),("Het huis is groot. Bovendien is het goedkoop.","A casa é grande. Além disso é barata."),("Schiet op, anders missen we de trein!","Despacha-te, senão perdemos o comboio!")],
  gram=[G("g-bijwoord-inversie","Advérbios de ligação = inversão","**daarom, toch, bovendien, anders, daarna, dus** são advérbios: ocupam a 1.ª posição e provocam **inversão**: *…, toch **heb ik** het gekocht.* **dus** admite as duas ordens no uso real: *dus ik neem* (falado) / *dus neem ik* (mais cuidado).",
    [("Ik was ziek. Daarom ben ik niet gekomen.","Estava doente. Por isso não vim.")],
    "Em português «por isso eu fui» e «por isso fui» são iguais; em neerlandês o verbo tem de vir logo a seguir.")],
  review=["v-daarom","v-daarna","v-toch"],
  cefr=C, exs=[
    MA([("dus","portanto"),("toch","mesmo assim"),("bovendien","além disso"),("anders","senão")], "Advérbios de ligação.", ["v-dus-conj","v-toch-conj","v-bovendien","v-anders"]),
    WO("Era caro; mesmo assim comprei-o.", ["Het","was","duur,","toch","heb","ik","het","gekocht"], "toch + inversão.", ["v-toch-conj"]),
    WO("Além disso é barata.", ["Bovendien","is","het","goedkoop"], "Inversão.", ["v-bovendien"]),
    TR("pt-nl","Despacha-te, senão perdemos o comboio!", ["Schiet op(,) anders missen we de trein","Opschieten(,) anders missen we de trein","Schiet op(,) anders missen wij de trein"], "anders + inversão.", ["v-anders"]),
    TR("nl-pt","Ik was ziek. Daarom ben ik niet gekomen.", ["Estava doente. Por isso não vim","Estive doente. Por isso não vim"], "daarom.", ["v-daarom"]),
    FE(["Het","huis","is","klein.","Bovendien","het","is","duur."], 5, "is het", "Depois de bovendien, inversão: Bovendien is het duur.", ["v-bovendien"]),
    MC("Qual liga com sentido de consequência?", ["*dus","toch|É concessão.","bovendien|É adição."], "dus = portanto.", ["v-dus-conj"]),
    FB("Ik had weinig tijd, ___ heb ik je geholpen.", ["toch"], "Concessão.", ["v-toch-conj"], choices=["toch","dus","bovendien"], tr="Tinha pouco tempo; mesmo assim ajudei-te."),
    LI("Neem een jas mee, anders krijg je het koud.", ["Neem een jas mee(,) anders krijg je het koud"], "Leva um casaco, senão ficas com frio.", "anders.", ["v-anders"]),
    MC("Ordem das palavras depois de «daarom»:", ["*verbo + sujeito (inversão)","sujeito + verbo|Isso é depois de want/maar.","verbo no fim|Isso é depois de omdat."], "Inversão.", ["v-daarom"]),
  ], diff=4, mins=7)

L(4, "Estruturar um texto", "Ten eerste, ten tweede, tot slot, kortom",
  ["Organizar ideias num texto ou discurso"],
  vocab=[V("v-ten-eerste","ten eerste","em primeiro lugar","expression"), V("v-ten-tweede","ten tweede","em segundo lugar","expression"),
         V("v-tot-slot","tot slot","por último|para terminar","expression"), V("v-kortom","kortom","em suma","adverb"),
         V("v-bijvoorbeeld","bijvoorbeeld","por exemplo","adverb",note="abrev. bijv. / bv.")],
  ex=[("Ten eerste is fietsen gezond.","Em primeiro lugar, andar de bicicleta é saudável."),("Ten tweede is het goedkoop.","Em segundo lugar, é barato."),("Tot slot is het goed voor het milieu.","Por último, é bom para o ambiente."),("Kortom: fietsen is ideaal.","Em suma: a bicicleta é ideal.")],
  review=["v-eerst","v-daarna","v-bovendien","v-uiteindelijk"],
  cefr=C, exs=[
    MA([("ten eerste","em primeiro lugar"),("ten tweede","em segundo lugar"),("tot slot","por último"),("kortom","em suma"),("bijvoorbeeld","por exemplo")], "Estrutura.", ["v-ten-eerste","v-ten-tweede","v-tot-slot","v-kortom","v-bijvoorbeeld"]),
    WO("Em primeiro lugar, andar de bicicleta é saudável.", ["Ten","eerste","is","fietsen","gezond"], "Inversão.", ["v-ten-eerste"]),
    TR("pt-nl","Por último, é bom para o ambiente.", ["Tot slot is het goed voor het milieu"], "Inversão.", ["v-tot-slot"]),
    TR("nl-pt","Kortom: fietsen is ideaal.", ["Em suma: andar de bicicleta é ideal","Em resumo: a bicicleta é ideal","Resumindo: andar de bicicleta é ideal"], "kortom.", ["v-kortom"]),
    FE(["Ten","tweede","het","is","goedkoop."], 2, "is het", "Inversão: Ten tweede is het goedkoop.", ["v-ten-tweede"]),
    MC("Para concluir um texto usa-se…", ["*Kortom, …","Ten eerste, …|Isso abre.","Bijvoorbeeld, …|Isso exemplifica."], "kortom.", ["v-kortom"]),
    FB("Ik sport graag, ___ hardlopen en zwemmen.", ["bijvoorbeeld"], "Exemplo.", ["v-bijvoorbeeld"], choices=["bijvoorbeeld","kortom","ten eerste"], tr="Gosto de desporto, por exemplo corrida e natação."),
    CO("text","Waarom ik Nederlands leer", "Ten eerste woon ik in Nederland, dus ik wil met mijn buren kunnen praten. Ten tweede helpt het bij mijn werk: veel klanten spreken geen Engels. Bovendien vind ik het leuk om nieuwe talen te leren. Tot slot wil ik later Nederlander worden, en daarvoor moet ik een examen doen. Kortom: Nederlands is voor mij heel belangrijk.",
       [("Qual é a segunda razão?", ["*Ajuda no trabalho","Gosta de línguas","Os vizinhos"]),("O que quer fazer mais tarde?", ["*Obter a nacionalidade neerlandesa","Voltar a Portugal","Ser professor"])],
       "Nederlander worden = naturalizar-se.", ["v-ten-eerste","v-ten-tweede","v-tot-slot","v-kortom"]),
    LI("Kortom, het was een geslaagde dag.", ["Kortom(,) het was een geslaagde dag"], "Em suma, foi um dia bem-sucedido.", "kortom.", ["v-kortom"]),
    SW("Escreva 4 frases sobre porque gosta (ou não) da sua cidade, com ten eerste, ten tweede, tot slot e kortom.", ["Ten eerste is mijn stad mooi. Ten tweede zijn er veel parken. Tot slot is het openbaar vervoer goed. Kortom: ik woon hier graag."], ["Os quatro conectores", "Inversão depois de cada um", "Uma conclusão"], 25, "Texto estruturado.", ["v-ten-eerste","v-tot-slot","v-kortom"]),
  ], diff=4, mins=8)

L(5, "Revisão: escolher o conector certo", "Coordenativas, subordinativas e advérbios.",
  ["Escolher o conector e a ordem certa em contexto"],
  vocab=[V("v-ondanks","ondanks","apesar de","preposition",note="ondanks de regen"), V("v-door","door","por causa de|devido a","preposition",note="door de staking"),
         V("v-daardoor","daardoor","por causa disso","adverb"), V("v-in-tegenstelling-tot","in tegenstelling tot","ao contrário de","expression")],
  ex=[("Ondanks de regen gingen we wandelen.","Apesar da chuva fomos passear."),("Door de staking rijden er geen treinen.","Devido à greve não há comboios."),("Ik sliep slecht. Daardoor was ik moe.","Dormi mal. Por causa disso estava cansado."),("In tegenstelling tot mijn broer ben ik vroeg op.","Ao contrário do meu irmão, levanto-me cedo.")],
  gram=[G("g-voorzetsel-vs-voegwoord","Preposição ou conjunção?","**ondanks** / **door** + **nome** (sem verbo): *ondanks de regen*. Com oração usa-se a conjunção: *hoewel het regent*, *omdat er een staking is*. **daardoor** (por causa disso) é advérbio: inversão.",
    [("Ondanks het slechte weer… = Hoewel het weer slecht is…","Apesar do mau tempo… = Embora o tempo esteja mau…")])],
  review=["v-hoewel","v-omdat","v-dus-conj","v-toch-conj","v-want"],
  cefr=C, exs=[
    MA([("ondanks","apesar de"),("door","devido a"),("daardoor","por causa disso"),("in tegenstelling tot","ao contrário de")], "Mais conectores.", ["v-ondanks","v-door","v-daardoor","v-in-tegenstelling-tot"]),
    FB("___ de regen gingen we wandelen.", ["Ondanks"], "Preposição + nome.", ["v-ondanks"], choices=["Ondanks","Hoewel","Maar"], tr="Apesar da chuva fomos passear."),
    FB("___ het regende, gingen we wandelen.", ["Hoewel"], "Conjunção + oração.", ["v-hoewel"], choices=["Hoewel","Ondanks","Door"], tr="Embora estivesse a chover, fomos passear."),
    FB("___ de staking rijden er geen treinen.", ["Door"], "Causa + nome.", ["v-door"], choices=["Door","Omdat","Want"], tr="Devido à greve não há comboios."),
    TR("pt-nl","Dormi mal. Por causa disso estava cansado.", ["Ik sliep slecht(.) Daardoor was ik moe","Ik heb slecht geslapen(.) Daardoor was ik moe","Ik heb slecht geslapen(.) Daardoor ben ik moe"], "daardoor + inversão.", ["v-daardoor"]),
    TR("nl-pt","In tegenstelling tot mijn broer ben ik vroeg op.", ["Ao contrário do meu irmão, levanto-me cedo","Ao contrário do meu irmão, acordo cedo"], "in tegenstelling tot.", ["v-in-tegenstelling-tot"]),
    FE(["Ondanks","het","regent,","gaan","we","fietsen."], 0, "Hoewel", "Com oração (het regent) usa-se hoewel.", ["v-ondanks","v-hoewel"]),
    MC("Complete: «Ik heb honger, ___ ik eet een broodje.»", ["*dus","omdat|Exigiria o verbo no fim e mudaria o sentido.","hoewel|Sentido errado."], "Consequência com ordem normal.", ["v-dus-conj"]),
    MC("Complete: «Ik ga naar bed ___ ik moe ben.»", ["*omdat","want|Com want seria «want ik ben moe».","dus|Sentido errado."], "Verbo no fim → omdat.", ["v-omdat"]),
    LI("Door het slechte weer is de wedstrijd afgelast.", ["Door het slechte weer is de wedstrijd afgelast"], "Devido ao mau tempo o jogo foi cancelado.", "door + nome.", ["v-door"]),
  ], diff=4, mins=7)

W()
